        if (lastAssistant && lastAssistant.finish_reason === 'stop') {
            console.log('Response complete: finish_reason is "stop"');
            return true;
        }

        // Check 2: If the assistant used tool calls, check if they've all been processed
        if (lastAssistant && lastAssistant.tool_calls && lastAssistant.tool_calls.length > 0) {
            const toolCallIds = lastAssistant.tool_calls.map(tc => tc.id);
            const toolResponses = allMessages.filter(m =>
