            const hasSubstantialContent = m.content.length > 20;

            // Check for natural language completion signals
            const hasCompletionMarkers = !m.content.endsWith('...') &&
                !m.content.match(/^I'm (thinking|processing|working|calculating)/);

            // Check for completed sentence structure (ends with period, question mark, etc.)
            const hasCompleteSentence = !!m.content.match(/[.!?]\s*$/);

            console.log(`Content checks: length=${hasSubstantialContent}, markers=${hasCompletionMarkers}, sentence=${hasCompleteSentence}`);

            // Consider complete if it meets most criteria
