            setTimeout(() => {
                if (socket.connected) {
                    addStatusMessage('warning', 'Socket health check timed out');
                    socket.disconnect();
                }
            }, 3000);
        } catch (err) {
            console.error('Socket connection test failed:', err);
            addStatusMessage('error', `Socket connection test failed: ${err.message}`);
        }
    }, [addStatusMessage]);

    // Start the stream to receive live screenshots
    const startStream = () => {
        console.log('Starting browser screenshot stream...');
        setStreamStatus('connecting');
        addStatusMessage('info', 'Connecting to browser stream...');

        if (streamSourceRef.current) {
            console.log('Closing existing stream before starting new one');
            stopStream();
        }

        initStream();
    };

    // Initialize the SSE stream with error handling and reconnection
    const initStream = () => {
        if (!sessionId) {
            console.error('Cannot start stream without a session ID');
            addStatusMessage('error', 'Cannot start stream: No session ID');
            return;
        }

        console.log(`Initializing SSE stream for session ${sessionId}`);
        const timestamp = Date.now();
        const streamUrl = `${SERVER_URL}/browser-stream/${sessionId}?_t=${timestamp}`;

        try {
            // Create a new EventSource with proper error handling
            const source = new EventSource(streamUrl);
            streamSourceRef.current = source;

            // Set up all event handlers in one go
            setupStreamEventHandlers(streamUrl);

            // Set a timeout to detect if connection is not established quickly
            const connectionTimeout = setTimeout(() => {
                if (streamStatus === 'connecting') {
                    console.warn('Stream connection timeout after 5 seconds');
                    addStatusMessage('warning', 'Stream connection timeout, retrying...');

                    // Force reconnection if we're still in connecting state
                    handleReconnect('timeout');
                }
            }, 5000);

            // Store the timeout ID for cleanup
            sourceTimeoutsRef.current = [
                ...(sourceTimeoutsRef.current || []),
                connectionTimeout
            ];

            setStreaming(true);
        } catch (error) {
            console.error('Error initializing stream:', error);
            addStatusMessage('error', `Stream error: ${error.message}`);
            setStreamStatus('error');

            // Try to reconnect after an error
            setTimeout(() => {
                if (streamStatus !== 'active') {
                    console.log('Attempting to reconnect stream after initialization error');
                    initStream();
                }
            }, 3000);
        }
    };

    // Set up all the event handlers for the stream
    const setupStreamEventHandlers = (streamUrl) => {
        const source = streamSourceRef.current;
        if (!source) {
            console.error('Cannot set up handlers, no stream source');
            return;
        }

        // Main data handler for screenshots
        source.onmessage = (event) => {
            try {
                // Check if it's a valid data URL
                if (event.data && event.data.startsWith('data:image/')) {
                    setBrowserImage(event.data);
                    setStreamStatus('active');

                    // Reset error count on successful message
                    streamErrorCountRef.current = 0;
                }
            } catch (error) {
                console.error('Error processing stream data:', error);
                streamErrorCountRef.current++;

                if (streamErrorCountRef.current > 5) {
                    addStatusMessage('warning', 'Multiple stream errors, connection may be unstable');
                }
            }
        };

        // Handle status events
        source.addEventListener('status', (event) => {
            try {
                const data = JSON.parse(event.data);
                console.log('Stream status event:', data);

                if (data.type === 'connected') {
                    setStreamStatus('active');
                    addStatusMessage('success', 'Browser stream connected');
                } else if (data.type === 'warning') {
                    setStreamStatus('warning');
                    addStatusMessage('warning', data.message || 'Stream warning');
                } else if (data.type === 'error') {
                    streamErrorCountRef.current++;
                    addStatusMessage('error', data.message || 'Stream error');
                } else if (data.type === 'recovery') {
                    addStatusMessage('info', 'Stream attempting to recover');
                    requestScreenshot(); // Try requesting a fresh screenshot
                }
            } catch (error) {
                console.error('Error handling status event:', error);
            }
        });

        // Handle errors
        source.onerror = (error) => {
            console.error('Stream error:', error);
            streamErrorCountRef.current++;

            if (streamStatus !== 'error') {
                setStreamStatus('error');
                addStatusMessage('error', 'Stream connection error');
            }

            // Attempt to reconnect
            handleReconnect('error');
        };

        // Handle connection open
        source.onopen = () => {
            console.log('Stream connection opened');
            setStreamStatus('active');
            addStatusMessage('success', 'Browser stream connected');
            streamErrorCountRef.current = 0;

            // Clear any connection timeouts
            if (sourceTimeoutsRef.current && sourceTimeoutsRef.current.length > 0) {
                sourceTimeoutsRef.current.forEach(timeout => clearTimeout(timeout));
                sourceTimeoutsRef.current = [];
            }
        };
    };

    // Handle reconnection with backoff
    const handleReconnect = (reason) => {
        const source = streamSourceRef.current;

        // Only handle reconnect if we have a source and are in the right states
        if (!source || streamStatus === 'inactive' || !streaming) {
            return;
        }

        // Close the existing connection
        try {
            source.close();
            streamSourceRef.current = null;
        } catch (e) {
            console.warn('Error closing stream connection:', e);
        }

        // Calculate backoff delay based on retry count
        const retryCount = streamErrorCountRef.current || 0;
        const backoffDelay = Math.min(30000, Math.pow(1.5, Math.min(retryCount, 10)) * 1000);

        console.log(`Stream reconnecting in ${Math.round(backoffDelay / 1000)}s (reason: ${reason}, attempts: ${retryCount})`);
        addStatusMessage('reconnecting', `Reconnecting in ${Math.round(backoffDelay / 1000)}s...`);

        // Schedule reconnection
        const reconnectTimeout = setTimeout(() => {
            console.log('Attempting to reconnect stream...');
            setStreamStatus('connecting');
            initStream();
        }, backoffDelay);

        // Store timeout for cleanup
        sourceTimeoutsRef.current = [
            ...(sourceTimeoutsRef.current || []).filter(t => t !== null),
            reconnectTimeout
        ];
    };

    // Scroll to bottom of messages
    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleSendMessage = async (e) => {
        e.preventDefault();

        if (!inputValue.trim()) return;
        if (!sessionId) {
            setError('Session not initialized. Please try again.');
            return;
        }

        // Add user message to state immediately
        const userMessage = { role: 'user', content: inputValue };
        setMessages([...messages, userMessage]);
        setInputValue('');
        setLoading(true);
        setError(null);

        try {
            const endpoint = `${SERVER_URL}/chat/${sessionId}`;

            console.log(`Sending message to ${endpoint}`);

            // First, emit the message over socket.io for faster processing
            const socket = io.connect(SOCKET_URL);
            socket.emit('chat-message', {
                sessionId,
                message: inputValue,
                timestamp: Date.now()
            });

            // Then also send it via HTTP as a backup
            const response = await axios.post(endpoint, {
                message: inputValue
            }, {
                timeout: 10000 // Shorter timeout since we're just getting an acknowledgment
            });

            // For the HTTP response, we only need to check for success
            // The actual message processing updates will come via WebSocket
            if (response.data.success) {
                console.log('Message received by server:', response.data.status);
                addStatusMessage('info', 'Message received by server, processing started');
            } else {
                setError(`Error: ${response.data.error}`);
                setLoading(false);
            }
        } catch (err) {
            console.error('Error sending message:', err);

            // Check if this is a 404 error (session not found)
            if (err.response && err.response.status === 404) {
                setError(`Your session has expired. Creating a new session...`);
                // Clear session ID to trigger re-initialization
                setSessionId(null);
                // Wait a moment and then initialize a new session
                setTimeout(async () => {
                    try {
                        const sessionResponse = await axios.post(`${SERVER_URL}/session`);
                        if (sessionResponse.data.success) {
                            setSessionId(sessionResponse.data.sessionId);
                            setError(`Session recreated! Please send your message again.`);
                            addStatusMessage('system', `New session initialized: ${sessionResponse.data.sessionId}`);
                        } else {
                            setError(`Error: ${sessionResponse.data.error}`);
                        }
                    } catch (sessionErr) {
                        setError(`Failed to create a new session: ${sessionErr.message}`);
                    }
                }, 1000);
                return;
            }

            // Handle other errors
            setError(`Error sending message: ${err.message}`);
            setLoading(false);
        }
    };

    // Add a function to request a screenshot
    const requestScreenshot = async () => {
        try {
            console.log("Requesting screenshot...");
            setError(null);
            const endpoint = `${SERVER_URL}/screenshot`;

            // Include the sessionId in the request if available
            const params = sessionId ? { sessionId } : {};

            // Add a cache-busting parameter
            params._t = Date.now();

            const response = await axios.get(endpoint, {
                params,
                timeout: 10000 // 10 second timeout
            });

            console.log("Screenshot requested successfully");
            return response; // Return the response for async/await
        } catch (err) {
            console.error("Error requesting screenshot:", err);
            addStatusMessage('warning', `Screenshot request failed: ${err.message}`);
            // Don't set error to UI to avoid disrupting the experience
            return null;
        }
    };

    const togglePreview = () => {
        setPreviewVisible(!previewVisible);

        // If hiding preview while streaming, stop the stream
        if (!previewVisible && streaming) {
            stopStream();
        }
    };

    return (
        <div className="app-container">
            <header className="app-header">
                <h1>OpenAI MCP Client</h1>
                <button
                    className="toggle-preview-button"
                    onClick={togglePreview}
                >
                    {previewVisible ? 'Hide Preview' : 'Show Preview'}
                </button>
            </header>

            <main className="main-content">
                <div className="chat-section">
                    <div className="chat-header">
                        <h2>Chat</h2>
                        <button
                            className="toggle-technical-button"
                            onClick={toggleTechnicalMessages}
                            title={showTechnicalMessages ? 'Hide technical details' : 'Show technical details'}
                        >
                            {showTechnicalMessages ? 'Hide Technical Details' : 'Show Technical Details'}
                        </button>
                    </div>
                    <div className="chat-container">
                        {messages
                            .filter(msg =>
                                ['user', 'assistant'].includes(msg.role) ||
                                (showTechnicalMessages && ['tool', 'system', 'function'].includes(msg.role))
                            )
                            .map((message, index) => (
                                <div key={index} className={`message ${message.role}`}>
                                    <div className="message-role">{message.role === 'function' ? 'tool-result' : message.role}</div>
                                    <div className="message-content">
                                        {message.role === 'function' || message.role === 'tool' ? (
                                            <pre className="tool-content">{typeof message.content === 'string' ? message.content : JSON.stringify(message.content, null, 2)}</pre>
                                        ) : (
                                            <div>{message.content}</div>
                                        )}
                                        {message.tool_calls && (
                                            <div className="tool-calls">
                                                <div className="tool-call-header">Tool Calls:</div>
                                                {message.tool_calls.map((tool, toolIndex) => (
                                                    <div key={toolIndex} className="tool-call">
                                                        <div className="tool-name">{tool.function?.name || 'Unknown Tool'}</div>
                                                        <pre className="tool-args">{tool.function?.arguments || '{}'}</pre>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        {error && (
                            <div className="message error">
                                <div className="message-role">Error</div>
                                <div className="message-content">{error}</div>
                            </div>
                        )}
                        {loading && (
                            <div className="message loading">
                                <div className="message-content">
                                    <div className="loading-spinner"></div>
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <form className="input-container" onSubmit={handleSendMessage}>
                        <input
                            type="text"
                            value={inputValue}
                            onChange={(e) => setInputValue(e.target.value)}
                            placeholder="Type your message..."
                            className="message-input"
                            disabled={loading || !sessionId}
                        />
                        <button
                            type="submit"
                            className="send-button"
                            disabled={loading || !sessionId || !inputValue.trim()}
                        >
                            Send
                        </button>
                    </form>
                </div>

                {previewVisible && (
                    <div className="preview-section">
                        <h2 className="preview-title">
                            Browser Preview
                            <div className="preview-controls">
                                {streaming ? (
                                    <button
                                        onClick={stopStream}
                                        className="stream-button stop"
                                        disabled={!sessionId}
                                    >
                                        Stop Stream
                                    </button>
                                ) : (
                                    <button
                                        onClick={startStream}
                                        className="stream-button start"
                                        disabled={!sessionId}
                                    >
                                        Start Stream
                                    </button>
                                )}
                                <button
                                    onClick={requestScreenshot}
                                    className="refresh-preview-button"
                                    disabled={!sessionId || streaming}
                                >
                                    Take Screenshot
                                </button>
                            </div>
                        </h2>
                        <div className={`stream-status ${streamStatus} ${streaming ? 'pulsing' : ''}`}>
                            {streamStatus === 'waiting' ? 'Test starting...' :
                                streamStatus === 'connecting' ? 'Connecting...' :
                                    streamStatus === 'connected' ? 'Test running' :
                                        streamStatus.charAt(0).toUpperCase() + streamStatus.slice(1)}
                        </div>
                        <div className="browser-preview">
                            {browserImage ? (
                                <img
                                    src={browserImage}
                                    alt="Browser preview"
                                    className="browser-image"
                                    title={streaming ? "Live stream" : "Static screenshot"}
                                />
                            ) : (
                                <div className="no-preview">
                                    No browser activity yet
                                </div>
                            )}
                        </div>

                        {/* Add status log section below the preview */}
                        <div className="status-log">
                            <h3>Status Log</h3>
                            <div className="status-messages">
                                {statusMessages.length === 0 ? (
                                    <div className="status-message info">
                                        <span className="status-time">--:--:--</span>
                                        <span className="status-text">Waiting for activity...</span>
                                    </div>
                                ) : (
                                    statusMessages.map((status, index) => (
                                        <div key={index} className={`status-message ${status.type}`}>
                                            <span className="status-time">{status.time}</span>
                                            <span className="status-text">{status.text}</span>
                                        </div>
                                    ))
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </main>
        </div>
    );
}

export default App;
